21	/**
22	 * Derives an owner's {@code locality} (canonical region), preferring the postcode range
23	 * (via {@link PostcodePolicy}) and falling back to a fixed city-to-region table when the
24	 * postcode is absent or in no known range.
25	 */
26	public final class LocalityResolver {
27	
28	    private static final String UNKNOWN = "UNKNOWN";
29	
30	    private static final Map<String, String> CITY_REGION = Map.of(
31	        "Sydney", "NSW",
32	        "Melbourne", "VIC",
33	        "Brisbane", "QLD");
34	
35	    private LocalityResolver() {
36	    }
37	
38	    /**
39	     * Resolve the canonical region for an owner, preferring the postcode.
40	     *
41	     * @param city the owner's city, may be {@code null}
42	     * @param postcode the owner's postcode, may be {@code null}
43	     * @return the region derived from the postcode range when it is known, otherwise the
44	     * region from the city table, or {@code "UNKNOWN"} when neither is known
45	     */
46	    public static String resolve(String city, String postcode) {
47	        return PostcodePolicy.regionForPostcode(postcode).orElseGet(() -> regionForCity(city));
48	    }
49	
50	    /**
51	     * Resolve an owner's locality from its {@code customerCode}, whose {@code REGION} prefix is the
52	     * canonical region. Falls back to {@link #resolve(String, String)} for owners that predate the
53	     * customer code (and so have none), keeping their locality unchanged.
54	     *
55	     * @param customerCode the owner's customer code, may be {@code null}
56	     * @param city the owner's city, used only for the fallback, may be {@code null}
57	     * @param postcode the owner's postcode, used only for the fallback, may be {@code null}
58	     * @return the region carried by the customer code, or the city/postcode-derived region when the
59	     * customer code is absent
60	     */
61	    public static String fromCustomerCode(String customerCode, String city, String postcode) {
62	        String region = CustomerCodeGenerator.region(customerCode);
63	        return region != null ? region : resolve(city, postcode);
64	    }
